package com.sistema.despertar;
import android.app.AlarmManager;import android.app.PendingIntent;import android.content.Context;import android.content.Intent;import android.content.SharedPreferences;import java.util.Calendar;import java.util.Map;import org.json.JSONObject;
final class ReminderScheduler {
 static final String EXTRA_ID="rid",EXTRA_TITLE="rtitle",EXTRA_DAYMASK="daymask",ACTION_SNOOZE="com.sistema.despertar.SNOOZE",ACTION_SNOOZED="com.sistema.despertar.SNOOZED";static final int DAY=24*60*60*1000;private static final String PREF="sistema_native_reminders";
 static PendingIntent pending(Context c,String id,String title,int mask){Intent i=new Intent(c,ReminderReceiver.class);i.putExtra(EXTRA_ID,id);i.putExtra(EXTRA_TITLE,title);i.putExtra(EXTRA_DAYMASK,mask);return PendingIntent.getBroadcast(c,id.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void persist(Context c,String id,String title,String mode,String time,int minutes,int mask){try{JSONObject o=new JSONObject();o.put("id",id);o.put("title",title);o.put("mode",mode);o.put("time",time);o.put("minutes",minutes);o.put("mask",mask);c.getSharedPreferences(PREF,Context.MODE_PRIVATE).edit().putString("r_"+id,o.toString()).apply();}catch(Exception ignored){}}
 static void daily(Context c,String id,String title,String hm,int mask){try{String[] p=hm.split(":");int hour=Integer.parseInt(p[0]),minute=Integer.parseInt(p[1]);Calendar cal=Calendar.getInstance();cal.set(Calendar.HOUR_OF_DAY,hour);cal.set(Calendar.MINUTE,minute);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);if(cal.getTimeInMillis()<=System.currentTimeMillis())cal.add(Calendar.DAY_OF_YEAR,1);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);a.setInexactRepeating(AlarmManager.RTC_WAKEUP,cal.getTimeInMillis(),DAY,pending(c,id,title,mask));persist(c,id,title,"daily",hm,0,mask);}catch(Exception ignored){}}
 static void interval(Context c,String id,String title,int minutes){try{long period=Math.max(30,minutes)*60L*1000L;long first=System.currentTimeMillis()+period;AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);a.setInexactRepeating(AlarmManager.RTC_WAKEUP,first,period,pending(c,id,title,127));persist(c,id,title,"interval","",minutes,127);}catch(Exception ignored){}}
 static void snooze(Context c,String id,String title){try{Intent i=new Intent(c,ReminderReceiver.class);i.setAction(ACTION_SNOOZED);i.putExtra(EXTRA_ID,"snooze_"+id);i.putExtra(EXTRA_TITLE,title);PendingIntent p=PendingIntent.getBroadcast(c,("snooze_"+id).hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+10*60*1000L,p);}catch(Exception ignored){}}
 static void cancel(Context c,String id){try{AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent p=pending(c,id,"",127);a.cancel(p);p.cancel();c.getSharedPreferences(PREF,Context.MODE_PRIVATE).edit().remove("r_"+id).apply();}catch(Exception ignored){}}
 static void restore(Context c){SharedPreferences p=c.getSharedPreferences(PREF,Context.MODE_PRIVATE);for(Map.Entry<String,?> e:p.getAll().entrySet()){try{JSONObject o=new JSONObject(String.valueOf(e.getValue()));String id=o.getString("id"),title=o.getString("title"),mode=o.getString("mode");if("daily".equals(mode))daily(c,id,title,o.getString("time"),o.optInt("mask",127));else interval(c,id,title,o.getInt("minutes"));}catch(Exception ignored){}}}
}
